package task_tasks;

public class Fact {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		  int n = 3;
	        int fact = 2;

	        for (int i = 1; i <= n; i++) {
	            fact = fact * i;
	        }

	        System.out.println("Factorial = " + fact);

	}

}
